function auth(PDO $db,bool $required=true): ?array { $h=$_SERVER['HTTP_AUTHORIZATION']??''; if(!preg_match('/^Bearer\s+([a-f0-9]{64})$/i',$h,$m)){if($required)err('Bearer token required.',401,'unauthorized');return null;} $q=$db->prepare('SELECT u.id,u.username,u.email,u.display_name,u.bio,u.avatar_media_id,u.website,u.`BlueTick`,u.created_at FROM sessions s JOIN users u ON u.id=s.user_id WHERE s.token_hash=? AND s.expires_at>UTC_TIMESTAMP() AND u.is_active=1');$q->execute([hash('sha256',$m[1])]);$u=$q->fetch();if(!$u&&$required)err('Session expired or invalid.',401,'invalid_token');return $u?:null; }
function token(PDO $db,int $uid,array $cfg): string { $t=bin2hex(random_bytes(32));$q=$db->prepare('INSERT INTO sessions(user_id,token_hash,expires_at,created_at) VALUES(?,?,DATE_ADD(UTC_TIMESTAMP(),INTERVAL ? DAY),UTC_TIMESTAMP())');$q->execute([$uid,hash('sha256',$t),(int)$cfg['token_ttl_days']]);return $t; }
function pub(array $u): array {
 foreach(['id','avatar_media_id'] as $k) if(isset($u[$k])) $u[$k]=(int)$u[$k];
 $u['BlueTick'] = filter_var($u['BlueTick'] ?? false, FILTER_VALIDATE_BOOLEAN);
 if (!empty($u['avatar_media_id'])) {
  global $db, $config;
  if (isset($db) && $db instanceof PDO) {
   $q=$db->prepare('SELECT stored_name FROM media WHERE id=?'); $q->execute([(int)$u['avatar_media_id']]); $stored=$q->fetchColumn();
   $u['avatar_url']=$stored ? rtrim((string)$config['upload_url'],'/').'/'.$stored : null;
  }
 } else { $u['avatar_url']=null; }
 unset($u['password_hash'],$u['is_active']); return $u;
}
function post(PDO $db,int $id,?int $viewer): ?array { $sql='SELECT p.id,p.user_id,p.body,p.media_id,p.reply_to_id,p.created_at,p.updated_at,u.username,u.display_name,u.avatar_media_id,u.`BlueTick`,(SELECT COUNT(*) FROM likes WHERE post_id=p.id) likes_count,(SELECT COUNT(*) FROM reposts WHERE post_id=p.id) reposts_count,(SELECT COUNT(*) FROM posts WHERE reply_to_id=p.id AND is_deleted=0) replies_count,'.($viewer?'EXISTS(SELECT 1 FROM likes WHERE post_id=p.id AND user_id='.(int)$viewer.')':'0').' liked,'.($viewer?'EXISTS(SELECT 1 FROM reposts WHERE post_id=p.id AND user_id='.(int)$viewer.')':'0').' reposted FROM posts p JOIN users u ON u.id=p.user_id WHERE p.id=? AND p.is_deleted=0';$q=$db->prepare($sql);$q->execute([$id]);$p=$q->fetch();if(!$p)return null;global $config;$pollQ=$db->prepare('SELECT id,created_at FROM polls WHERE post_id=?');$pollQ->execute([$id]);$poll=$pollQ->fetch();if($poll){$pollId=(int)$poll['id'];$optQ=$db->prepare('SELECT o.id,o.option_text,COUNT(v.user_id) votes_count FROM poll_options o LEFT JOIN poll_votes v ON v.option_id=o.id AND v.poll_id=o.poll_id WHERE o.poll_id=? GROUP BY o.id,o.option_text,o.position ORDER BY o.position');$optQ->execute([$pollId]);$options=$optQ->fetchAll();foreach($options as &$option){$option['id']=(int)$option['id'];$option['votes_count']=(int)$option['votes_count'];}unset($option);$voteQ=$db->prepare('SELECT option_id FROM poll_votes WHERE poll_id=? AND user_id=?');$voteQ->execute([$pollId,$viewer??0]);$myVote=$voteQ->fetchColumn();$p['poll']=['id'=>$pollId,'created_at'=>$poll['created_at'],'options'=>$options,'total_votes'=>array_sum(array_column($options,'votes_count')),'my_vote_option_id'=>$myVote===false?null:(int)$myVote];}else{$p['poll']=null;}if(!empty($p['avatar_media_id'])){$aq=$db->prepare('SELECT stored_name FROM media WHERE id=?');$aq->execute([(int)$p['avatar_media_id']]);$av=$aq->fetchColumn();$p['avatar_url']=$av?rtrim((string)$config['upload_url'],'/').'/'.$av:null;}else{$p['avatar_url']=null;}$p['BlueTick']=filter_var($p['BlueTick']??false,FILTER_VALIDATE_BOOLEAN);if(!empty($p['media_id'])){$mq=$db->prepare('SELECT stored_name FROM media WHERE id=?');$mq->execute([$p['media_id']]);$stored=$mq->fetchColumn();$p['media_url']=$stored?rtrim((string)$config['upload_url'],'/').'/'.$stored:null;}else{$p['media_url']=null;}foreach(['id','user_id','media_id','reply_to_id','likes_count','reposts_count','replies_count'] as $k)$p[$k]=$p[$k]===null?null:(int)$p[$k];$p['liked']=(bool)$p['liked'];$p['reposted']=(bool)$p['reposted'];return $p; }
