  $comments=$count('SELECT COUNT(*) FROM posts p JOIN posts c ON c.reply_to_id=p.id WHERE p.user_id=? AND p.is_deleted=0 AND c.is_deleted=0');
  $views=0;$dwell=0;$top=[];
